native_functions.RandomPCG.ush::Rand3DPCG16:
uint3 Rand3DPCG16(int3 p)
{
	// taking a signed int then reinterpreting as unsigned gives good behavior for negatives
	uint3 v = uint3(p);

	// Linear congruential step. These LCG constants are from Numerical Recipies
	// For additional #'s, PCG would do multiple LCG steps and scramble each on output
	// So v here is the RNG state
	v = v * 1664525u + 1013904223u;

	// PCG uses xorshift for the final shuffle, but it is expensive (and cheap
	// versions of xorshift have visible artifacts). Instead, use simple MAD Feistel steps
	//
	// Feistel ciphers divide the state into separate parts (usually by bits)
	// then apply a series of permutation steps one part at a time. The permutations
	// use a reversible operation (usually ^) to part being updated with the result of
	// a permutation function on the other parts and the key.
	//
	// In this case, I'm using v.x, v.y and v.z as the parts, using + instead of ^ for
	// the combination function, and just multiplying the other two parts (no key) for 
	// the permutation function.
	//
	// That gives a simple mad per round.
	v.x += v.y*v.z;
	v.y += v.z*v.x;
	v.z += v.x*v.y;
	v.x += v.y*v.z;
	v.y += v.z*v.x;
	v.z += v.x*v.y;

	// only top 16 bits are well shuffled
	return v >> 16u;
}

native_functions.Random.ush::SimplexCorners:
float4x3 SimplexCorners(float3 v)
{
	// find base corner by skewing to tetrahedral space and back
	float3 tet = floor(v + v.x/3 + v.y/3 + v.z/3);
	float3 base = tet - tet.x/6 - tet.y/6 - tet.z/6;
	float3 f = v - base;

	// Find offsets to other corners (McEwan did this in tetrahedral space,
	// but since skew is along x=y=z axis, this works in Euclidean space too.)
	float3 g = step(f.yzx, f.xyz), h = 1 - g.zxy;
	float3 a1 = min(g, h) - 1. / 6., a2 = max(g, h) - 1. / 3.;

	// four corners
	return float4x3(base, base + a1, base + a2, base + 0.5);
}

native_functions.Random.ush::SimplexSmooth:
float4 SimplexSmooth(float4x3 f)
{
	const float scale = 1024. / 375.;	// scale factor to make noise -1..1
	float4 d = float4(dot(f[0], f[0]), dot(f[1], f[1]), dot(f[2], f[2]), dot(f[3], f[3]));
	float4 s = saturate(2 * d);
	return (1 * scale + s*(-3 * scale + s*(3 * scale - s*scale)));
}

native_functions.Random.ush::SimplexDSmooth:
float3x4 SimplexDSmooth(float4x3 f)
{
	const float scale = 1024. / 375.;	// scale factor to make noise -1..1
	float4 d = float4(dot(f[0], f[0]), dot(f[1], f[1]), dot(f[2], f[2]), dot(f[3], f[3]));
	float4 s = saturate(2 * d);
	s = -12 * scale + s*(24 * scale - s * 12 * scale);

	return float3x4(
		s * float4(f[0][0], f[1][0], f[2][0], f[3][0]),
		s * float4(f[0][1], f[1][1], f[2][1], f[3][1]),
		s * float4(f[0][2], f[1][2], f[2][2], f[3][2]));
}

native_functions.Random.ush::NoiseTileWrap:
float3 NoiseTileWrap(float3 v,  bool bTiling, float RepeatSize)
{
	return bTiling ? (frac(v / RepeatSize) * RepeatSize) : v;
}

native_functions.Random.ush::JacobianSimplex_ALU:
float3x4 JacobianSimplex_ALU(float3 v, bool bTiling, float RepeatSize)
{
	// corners of tetrahedron
	float4x3 T = SimplexCorners(v);
	uint3 rand;
	float4x3 gvec[3], fv;
	float3x4 grad;

	// processing of tetrahedral vertices, unrolled
	// to compute gradient at each corner
	fv[0] = v - T[0];
	rand = Rand3DPCG16(int3(floor(NoiseTileWrap(6 * T[0] + 0.5, bTiling, RepeatSize))));
	gvec[0][0] = float3(rand.xxx & MGradientMask) * MGradientScale - 1;
	gvec[1][0] = float3(rand.yyy & MGradientMask) * MGradientScale - 1;
	gvec[2][0] = float3(rand.zzz & MGradientMask) * MGradientScale - 1;
	grad[0][0] = dot(gvec[0][0], fv[0]);
	grad[1][0] = dot(gvec[1][0], fv[0]);
	grad[2][0] = dot(gvec[2][0], fv[0]);

	fv[1] = v - T[1];
	rand = Rand3DPCG16(int3(floor(NoiseTileWrap(6 * T[1] + 0.5, bTiling, RepeatSize))));
	gvec[0][1] = float3(rand.xxx & MGradientMask) * MGradientScale - 1;
	gvec[1][1] = float3(rand.yyy & MGradientMask) * MGradientScale - 1;
	gvec[2][1] = float3(rand.zzz & MGradientMask) * MGradientScale - 1;
	grad[0][1] = dot(gvec[0][1], fv[1]);
	grad[1][1] = dot(gvec[1][1], fv[1]);
	grad[2][1] = dot(gvec[2][1], fv[1]);

	fv[2] = v - T[2];
	rand = Rand3DPCG16(int3(floor(NoiseTileWrap(6 * T[2] + 0.5, bTiling, RepeatSize))));
	gvec[0][2] = float3(rand.xxx & MGradientMask) * MGradientScale - 1;
	gvec[1][2] = float3(rand.yyy & MGradientMask) * MGradientScale - 1;
	gvec[2][2] = float3(rand.zzz & MGradientMask) * MGradientScale - 1;
	grad[0][2] = dot(gvec[0][2], fv[2]);
	grad[1][2] = dot(gvec[1][2], fv[2]);
	grad[2][2] = dot(gvec[2][2], fv[2]);

	fv[3] = v - T[3];
	rand = Rand3DPCG16(int3(floor(NoiseTileWrap(6 * T[3] + 0.5, bTiling, RepeatSize))));
	gvec[0][3] = float3(rand.xxx & MGradientMask) * MGradientScale - 1;
	gvec[1][3] = float3(rand.yyy & MGradientMask) * MGradientScale - 1;
	gvec[2][3] = float3(rand.zzz & MGradientMask) * MGradientScale - 1;
	grad[0][3] = dot(gvec[0][3], fv[3]);
	grad[1][3] = dot(gvec[1][3], fv[3]);
	grad[2][3] = dot(gvec[2][3], fv[3]);

	// blend gradients
	float4 sv = SimplexSmooth(fv);
	float3x4 ds = SimplexDSmooth(fv);

	float3x4 jacobian;
	jacobian[0] = float4(mul(sv, gvec[0]) + mul(ds, grad[0]), dot(sv, grad[0]));
	jacobian[1] = float4(mul(sv, gvec[1]) + mul(ds, grad[1]), dot(sv, grad[1]));
	jacobian[2] = float4(mul(sv, gvec[2]) + mul(ds, grad[2]), dot(sv, grad[2]));

	return jacobian;
}

native_functions.NiagaraSimplexNoise.cpp::Rand3DPCG16:
FIntVector Rand3DPCG16(FIntVector p)
{
	constexpr uint32 Mul = 1664525u;
	constexpr uint32 Add = 1013904223u;

	uint32 X = uint32(p.X) * Mul + Add;
	uint32 Y = uint32(p.Y) * Mul + Add;
	uint32 Z = uint32(p.Z) * Mul + Add;

	X += Y * Z;
	Y += Z * X;
	Z += X * Y;
	X += Y * Z;
	Y += Z * X;
	Z += X * Y;

	return FIntVector(X >> 16, Y >> 16, Z >> 16);
}

native_functions.NiagaraSimplexNoise.cpp::SimplexNoiseOff:
FVector3f SimplexNoiseOffsetFromSeed(uint32 Seed)
{
	FIntVector Rand = Rand3DPCG16(FIntVector(Seed, Seed, Seed));
	return FVector3f(Rand.X, Rand.Y, Rand.Z) * (1.0f / 100.0f);
}

native_functions.NiagaraSimplexNoise.cpp::SimplexGvec:
FVector3f SimplexGvec(int Rand)
{
	FVector3f MGradientScale(1.f / 0x4000, 1.f / 0x2000, 1.f / 0x1000);
	return FVector3f(float(Rand & 0x8000), float(Rand & 0x4000), float(Rand & 0x2000)) * MGradientScale - FVector3f(1.f);
}

native_functions.NiagaraSimplexNoise.cpp::JacobianSimplex:
FNiagaraMatrix3x4 JacobianSimplex_ALU(FVector3f V)
{
	// SimplexCorners in Random.ush
	float SkewAmount = (V.X + V.Y + V.Z) * (1.0f / 3.0f);
	FVector3f Tet {
		FGenericPlatformMath::FloorToFloat(V.X + SkewAmount),
		FGenericPlatformMath::FloorToFloat(V.Y + SkewAmount),
		FGenericPlatformMath::FloorToFloat(V.Z + SkewAmount)
	};
	FVector3f Base = Tet - FVector3f((Tet.X + Tet.Y + Tet.Z) * (1.0f / 6.0f));
	FVector3f F = V - Base;

	FVector3f G {
		F.X >= F.Y ? 1.0f : 0.0f,
		F.Y >= F.Z ? 1.0f : 0.0f,
		F.Z >= F.X ? 1.0f : 0.0f
	};
	FVector3f H { 1.0f - G.Z, 1.0f - G.X, 1.0f - G.Y };

	FVector3f A1 = G.ComponentMin(H) - FVector3f(1.f / 6.f);
	FVector3f A2 = G.ComponentMax(H) - FVector3f(1.f / 3.f);

	FVector3f TetCorners[4] {
		Base,
		Base + A1,
		Base + A2,
		Base + FVector3f(0.5f)
	};

	// Actual Jacobian calc
	FNiagaraMatrix3x4 Jacobian;

	for (int CornerIndex = 0; CornerIndex < 4; CornerIndex++)
	{
		FVector3f RelVec = V - TetCorners[CornerIndex];
		FIntVector Rand = Rand3DPCG16(NiagaraVectorFloorToInt(6 * TetCorners[CornerIndex] + 0.5));

		FVector3f GvecX = SimplexGvec(Rand.X);
		FVector3f GvecY = SimplexGvec(Rand.Y);
		FVector3f GvecZ = SimplexGvec(Rand.Z);

		float GradX = GvecX.Dot(RelVec);
		float GradY = GvecY.Dot(RelVec);
		float GradZ = GvecZ.Dot(RelVec);

		// Shared terms
		constexpr float Scale = 1024.f / 375.f;
		float SquaredDist = RelVec.Dot(RelVec);
		float S = FMath::Clamp(SquaredDist + SquaredDist, 0.0f, 1.0f);

		// sv / SimplexSmooth in Random.ush
		float SimplexValue = Scale * (1.0f + S * (-3.0f + S * (3.0f - S)));

		// ds / SimplexDSmooth in Random.ush
		float DerivScale = Scale * (-12.0f + S * (24.0f - S * 12.0f));

		Jacobian[0] += FVector4f(SimplexValue * GvecX + (DerivScale * GradX) * RelVec, SimplexValue * GradX);
		Jacobian[1] += FVector4f(SimplexValue * GvecY + (DerivScale * GradY) * RelVec, SimplexValue * GradY);
		Jacobian[2] += FVector4f(SimplexValue * GvecZ + (DerivScale * GradZ) * RelVec, SimplexValue * GradZ);
	}

	return Jacobian;
}

